-- Reconstructed LC Pro Full Stack content part 1 (modules 1–3) from the verified LC Pro production state.
-- The remote migration version already exists; this file restores repository reproducibility.

with payload as (
  select * from jsonb_to_recordset($modules$[{"title":"Fundamentos de Engenharia Web","position":1,"description":"Ambiente profissional, Git, arquitetura Web e critérios de qualidade antes de construir o produto."},{"title":"Frontend Profissional","position":2,"description":"HTML semântico, CSS responsivo, acessibilidade, componentes e experiência de interface."},{"title":"JavaScript, TypeScript e React","position":3,"description":"Estado, eventos, módulos, consumo de APIs, tratamento de erros e organização de código."}]$modules$::jsonb)
  as x(position int,title text,description text)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
update nexora.modules m
set title=p.title,description=p.description
from payload p,c
where m.course_id=c.id and m.position=p.position;

with payload as (
  select * from jsonb_to_recordset($lessons$[{"title":"Da demanda ao critério de aceite","content":[{"body":"Uma equipe pede “um painel de pedidos melhor”. Se o desenvolvimento começa pela interface, é fácil entregar uma tela bonita que não resolve o problema. O trabalho profissional começa ao separar usuário, objetivo, dados, regras e evidências de sucesso.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Critério de aceite descreve um comportamento observável. Ele reduz ambiguidade porque permite responder objetivamente se a feature está pronta. Um bom critério evita palavras como “intuitivo”, “rápido” ou “correto” sem explicar como verificar.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Identifique quem executa a ação e por quê.","Liste entradas, regras e estados relevantes.","Escreva resultados observáveis, inclusive erro e vazio.","Transforme cada requisito crítico em caso de teste."],"title":"Como pensar na prática"},{"body":"Para “filtrar pedidos atrasados”, um critério verificável seria: dado um pedido com prazo anterior a hoje e status aberto, ele aparece no filtro Atrasados; pedidos concluídos não aparecem.","type":"example","title":"Exemplo aplicado"},{"body":"Começar pelo framework cria compromisso técnico antes de entender o problema. Depois, qualquer mudança de regra parece “retrabalho”, quando na verdade a regra nunca foi definida.","type":"mistake","title":"Falha que parece pequena"},{"body":"Pegue a demanda “usuário pode editar perfil”. Escreva três critérios: caminho de sucesso, dado inválido e tentativa de editar um perfil de outra pessoa.","type":"guided_practice","title":"Prática orientada"},{"body":"Tickets, PRs e revisões ficam muito mais eficientes quando a equipe discute comportamento esperado em vez de gosto pessoal. Critérios claros também protegem prazo e escopo.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Feature começa por comportamento verificável.","Critérios de aceite ligam negócio, implementação e teste.","Erros e estados vazios fazem parte do requisito.","Tecnologia vem depois da modelagem."]}],"lab_type":"checkpoint","position":1,"objective":"Transformar uma solicitação de negócio em comportamento verificável antes de escolher tecnologia.","xp_reward":130,"difficulty":1,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["A tela deve ficar moderna.","O sistema deve ser rápido.","Ao enviar e-mail inválido, o formulário impede o envio e informa o campo.","Use React porque é profissional."],"feedback":"Correto. O critério descreve entrada, comportamento e resultado observável.","question":"Qual requisito está mais próximo de um critério de aceite verificável?","feedback_incorrect":"Procure uma frase que outra pessoa consiga testar sem interpretar gosto ou intenção."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":1,"estimated_minutes":32},{"title":"Arquitetura Web ponta a ponta","content":[{"body":"Quando um botão “Salvar” falha, o defeito pode estar na validação do navegador, na requisição HTTP, na autorização do backend, em uma constraint do banco ou numa integração externa. Sem um mapa mental das camadas, depuração vira tentativa e erro.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Arquitetura Web separa responsabilidades. O cliente apresenta e coleta interação; a API valida e executa regras; o banco persiste estado; serviços externos ampliam capacidades. A separação não é burocracia: ela define onde cada decisão deve morar.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Cliente nunca é fonte confiável para autorização.","Backend valida novamente dados críticos.","Banco protege invariantes com tipos, constraints e transações.","Integrações externas precisam de timeout, erro e idempotência."],"title":"Como pensar na prática"},{"body":"Um cadastro envia JSON via HTTPS. A API valida formato, verifica permissão, grava o usuário e devolve 201. Se o e-mail já existir, a constraint impede duplicidade e a API traduz isso para um erro compreensível.","type":"example","title":"Exemplo aplicado"},{"body":"Confiar no campo hidden `role=admin` porque a interface não permite editá-lo é um erro de fronteira de confiança: qualquer cliente pode construir outra requisição.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe o fluxo de “criar tarefa” em cinco caixas: UI, requisição, API, banco e resposta. Marque em qual camada ocorre validação de formato, autorização e unicidade.","type":"guided_practice","title":"Prática orientada"},{"body":"Quem sabe localizar a responsabilidade de um erro reduz tempo de diagnóstico e escreve mudanças menores. Arquitetura é também uma ferramenta de manutenção.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Camadas têm responsabilidades diferentes.","O servidor é a fronteira de confiança para regras críticas.","O banco deve proteger invariantes persistentes.","Integrações precisam ser tratadas como falhas possíveis."]}],"lab_type":"checkpoint","position":2,"objective":"Explicar o caminho de uma requisição entre navegador, servidor, API, banco e serviços externos.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Somente no botão da interface.","No backend antes de executar a operação.","Apenas no CSS da página.","No navegador do usuário."],"feedback":"Correto. A autorização precisa ser aplicada numa fronteira controlada pelo servidor.","question":"Onde a autorização de uma operação sensível deve ser obrigatoriamente validada?","feedback_incorrect":"A interface melhora UX, mas não é uma barreira de segurança."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":1,"estimated_minutes":34},{"title":"Ambiente reproduzível e configuração","content":[{"body":"“Na minha máquina funciona” quase sempre significa que existe estado não documentado: versão, variável, serviço, arquivo local ou passo manual. Um projeto profissional precisa transformar essas dependências em instruções reproduzíveis.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Reprodutibilidade exige separar código de configuração. Código vai para o repositório; segredos e valores por ambiente entram por variáveis; comandos recorrentes viram scripts; dependências ficam declaradas e travadas por lockfile.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Documente pré-requisitos e comandos de início.","Use `.env.example` sem valores secretos.","Nunca versione tokens, senhas ou chaves privadas.","Mantenha lockfile e scripts de build/teste."],"title":"Como pensar na prática"},{"body":"Um README pode exigir apenas: copiar `.env.example` para `.env`, preencher `DATABASE_URL`, instalar dependências e executar os scripts padronizados. O objetivo é remover conhecimento tribal.","type":"example","title":"Exemplo aplicado"},{"body":"Colocar uma chave real em `.env.example` ainda é vazamento. O arquivo de exemplo deve conter nomes e formatos fictícios, nunca credenciais utilizáveis.","type":"mistake","title":"Falha que parece pequena"},{"body":"Imagine que outra pessoa acabou de clonar o projeto. Escreva o menor conjunto de passos que leva do clone a uma aplicação rodando e a um teste executado.","type":"guided_practice","title":"Prática orientada"},{"body":"Onboarding, CI e incidentes dependem da mesma propriedade: ser possível reconstruir o ambiente sem depender da memória de uma pessoa.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Configuração varia por ambiente; código não deve carregar segredos.","Lockfiles reduzem variação entre instalações.","Scripts padronizam tarefas repetíveis.","README deve ser executável, não decorativo."]}],"lab_type":"checkpoint","position":3,"objective":"Organizar projeto, comandos e variáveis de ambiente de forma que outra pessoa consiga executar a aplicação.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":[".env com a senha real do banco",".env.example com nomes de variáveis e valores fictícios","backup.sql com dados reais de clientes","private-key.pem"],"feedback":"Correto. Um arquivo de exemplo documenta configuração sem expor credenciais.","question":"Qual arquivo pode ser versionado com segurança?","feedback_incorrect":"Documentação pode ser pública; segredos e dados reais não."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":1,"estimated_minutes":36},{"title":"Git como sistema de mudança segura","content":[{"body":"Git não serve apenas para “salvar código”. Em equipes, ele registra decisões, permite revisar diferenças, isola mudanças e cria pontos seguros de retorno. Uma história de commits ruim transforma investigação e rollback em trabalho manual.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Uma mudança saudável tem escopo pequeno, mensagem explicativa e pode ser revisada independentemente. Branches isolam trabalho; pull requests tornam o diff discutível; tags e commits identificam versões; revert cria uma correção auditável sem reescrever história compartilhada.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Commit deve representar uma unidade coerente de mudança.","Evite misturar refactor, feature e formatação sem necessidade.","Revise o diff antes de enviar.","Prefira revert a apagar histórico compartilhado."],"title":"Como pensar na prática"},{"body":"Se uma feature causa erro em produção, `git revert <commit>` cria um novo commit que desfaz a mudança. A equipe preserva a evidência do que aconteceu e consegue reintroduzir a feature depois de corrigida.","type":"example","title":"Exemplo aplicado"},{"body":"Usar `git push --force` em branch compartilhada para “limpar” erros pode apagar trabalho de outras pessoas e destruir referências usadas em incidentes.","type":"mistake","title":"Falha que parece pequena"},{"body":"Planeje uma feature de autenticação em pelo menos três commits revisáveis: estrutura, validação e testes. Explique o que seria arriscado colocar tudo num único commit.","type":"guided_practice","title":"Prática orientada"},{"body":"História legível reduz custo de code review, `git bisect`, auditoria e rollback. Versionamento é parte da operação do produto.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Commit pequeno reduz raio de impacto.","PR é uma unidade de revisão, não só aprovação formal.","Rollback precisa ser previsível.","Histórico compartilhado deve permanecer auditável."]}],"lab_type":"checkpoint","position":4,"objective":"Usar branches, commits, pull requests e rollback como mecanismos de controle de risco.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Apagar a branch principal.","Usar revert para criar uma mudança inversa auditável.","Reescrever todo o histórico com force push.","Excluir o repositório e clonar novamente."],"feedback":"Correto. Revert preserva a história e adiciona uma reversão explícita.","question":"Qual ação é mais adequada para desfazer um commit já publicado numa branch compartilhada?","feedback_incorrect":"Em histórico compartilhado, prefira uma mudança auditável a reescrever commits existentes."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":1,"estimated_minutes":28},{"title":"HTTP, JSON e contratos entre camadas","content":[{"body":"Frontend e backend evoluem separadamente. Quando o contrato é implícito, uma mudança de nome de campo ou status HTTP pode quebrar a aplicação mesmo que cada lado continue “funcionando” isoladamente.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Contrato de API define método, caminho, autenticação, entrada, saída e erros. JSON é apenas um formato; a qualidade vem da estabilidade semântica. Status HTTP comunica classes de resultado e o corpo adiciona contexto estruturado.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["GET lê; POST cria ou dispara operação; PATCH altera parcialmente; DELETE remove.","2xx indica sucesso; 4xx representa problema da requisição/cliente; 5xx falha do servidor.","Erros devem ter código estável e mensagem legível.","Clientes não devem depender de texto de erro para lógica."],"title":"Como pensar na prática"},{"body":"Um POST `/api/tasks` pode receber `{title, dueAt}` e responder 201 com `{id,title,dueAt}`. Se `title` estiver vazio, responde 422 com `{error:\"validation_error\", fields:{title:\"required\"}}`.","type":"example","title":"Exemplo aplicado"},{"body":"Responder 200 para todo erro e colocar `{success:false}` no corpo obriga clientes e observabilidade a reinventar semântica que o protocolo já oferece.","type":"mistake","title":"Falha que parece pequena"},{"body":"Especifique o contrato de `PATCH /api/profile`: campos aceitos, resposta de sucesso, erro de validação e tentativa não autorizada.","type":"guided_practice","title":"Prática orientada"},{"body":"Contratos claros permitem gerar documentação, testes de integração e clientes mais resistentes. Também reduzem conversas do tipo “o backend mudou e ninguém avisou”.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["API é um contrato, não uma coleção de URLs.","Status HTTP e corpo têm papéis complementares.","Erros estruturados são parte do contrato.","Mudança de contrato exige coordenação e teste."]}],"lab_type":"checkpoint","position":5,"objective":"Modelar requests e responses com métodos, status, payloads e erros consistentes.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["200 com texto 'deu erro'","422 com erro estruturado de validação","500 porque o usuário errou","301 para a página inicial"],"feedback":"Correto. A requisição chegou ao recurso, mas falhou numa regra de validação.","question":"Qual resposta é mais coerente para um JSON válido cujo campo obrigatório está vazio?","feedback_incorrect":"Diferencie falha do servidor de entrada que não satisfaz o contrato."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":1,"estimated_minutes":30},{"title":"HTML semântico como estrutura de produto","content":[{"body":"Uma interface pode parecer correta visualmente e ainda ser difícil de navegar por teclado ou tecnologia assistiva. Quando tudo vira `div`, a estrutura existe apenas no CSS e na memória de quem escreveu.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Semântica comunica função: `main` identifica conteúdo principal, `nav` navegação, `button` ação, `form` coleta de dados. O navegador oferece comportamento, foco e acessibilidade nativos que componentes genéricos precisam recriar manualmente.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Use elementos pela função, não pela aparência.","Mantenha hierarquia de títulos coerente.","Todo controle precisa de nome acessível.","Imagem decorativa usa alt vazio; conteúdo relevante precisa de descrição."],"title":"Como pensar na prática"},{"body":"Um botão que abre um modal deve ser `<button type=\"button\">`, não uma `div` com `onclick`. Ele já participa da ordem de foco e responde a teclado sem código extra.","type":"example","title":"Exemplo aplicado"},{"body":"Adicionar `role=\"button\"` a uma `div` não cria automaticamente comportamento de teclado, estado disabled ou semântica completa. O elemento nativo costuma ser a opção mais robusta.","type":"mistake","title":"Falha que parece pequena"},{"body":"Revise uma tela imaginária de checkout e liste quais regiões seriam `header`, `main`, `form`, `fieldset`, `button` e `aside`.","type":"guided_practice","title":"Prática orientada"},{"body":"Semântica correta reduz bugs de interação e custo de acessibilidade. É uma decisão de engenharia, não acabamento posterior.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Elementos nativos carregam comportamento útil.","Semântica melhora teclado, leitura e manutenção.","Hierarquia deve refletir o documento.","Acessibilidade começa na estrutura."]}],"lab_type":"checkpoint","position":1,"objective":"Construir páginas cuja hierarquia continue compreensível para pessoas, leitores de tela e mecanismos de navegação.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["div","span","button type=\"submit\"","h3"],"feedback":"Correto. O botão nativo já possui semântica e comportamento adequados.","question":"Qual elemento é a melhor base para uma ação que envia um formulário?","feedback_incorrect":"Escolha o elemento cuja função corresponde à ação."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":2,"estimated_minutes":34},{"title":"CSS previsível: cascata, tokens e layout","content":[{"body":"Interfaces degradam quando cada ajuste adiciona mais um seletor específico, `!important` ou margem isolada. O sintoma aparece no visual, mas a causa é ausência de regras de composição.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"CSS previsível depende de poucas fontes de verdade: tokens para espaçamento, cores e tipografia; classes com responsabilidade clara; Grid/Flex para relações; cascata consciente para variantes. A meta não é eliminar a cascata, mas torná-la legível.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Defina escalas reutilizáveis para espaço e tamanho.","Prefira composição a seletores profundamente aninhados.","Use Grid para relações bidimensionais e Flex para alinhamento em eixo.","Evite valores mágicos quando representam o mesmo conceito."],"title":"Como pensar na prática"},{"body":"Um card pode usar `gap: var(--space-3)` internamente e o grid `gap: var(--space-4)`. Se o sistema precisar ficar mais compacto, a alteração ocorre nos tokens em vez de dezenas de arquivos.","type":"example","title":"Exemplo aplicado"},{"body":"`margin-left: 17px` pode resolver uma captura de tela específica, mas costuma quebrar quando texto, idioma ou viewport mudam.","type":"mistake","title":"Falha que parece pequena"},{"body":"Descreva um sistema mínimo de tokens para uma tela: três espaçamentos, três tamanhos de texto e dois raios. Depois associe cada valor a uma função.","type":"guided_practice","title":"Prática orientada"},{"body":"Design systems eficazes começam com consistência de regras, não com um catálogo gigante de componentes. Código visual previsível acelera produto e revisão.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Tokens representam decisões repetidas.","Baixa especificidade facilita composição.","Layout deve modelar relações, não coordenadas fixas.","Correção local recorrente sinaliza problema de sistema."]}],"lab_type":"checkpoint","position":2,"objective":"Organizar estilos com baixa especificidade, tokens e sistemas de layout em vez de correções locais acumuladas.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Criar um valor novo em cada componente.","Usar uma escala de tokens recorrentes.","Adicionar !important a todas as margens.","Posicionar tudo com absolute."],"feedback":"Correto. Uma escala recorrente transforma espaçamento em regra compartilhada.","question":"Qual abordagem tende a reduzir inconsistência de espaçamento ao longo do produto?","feedback_incorrect":"Consistência nasce de poucas decisões reutilizadas, não de ajustes independentes."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":2,"estimated_minutes":36},{"title":"Responsividade mobile-first e interfaces fluidas","content":[{"body":"Uma lista de breakpoints baseada em modelos de celular envelhece rápido. O problema real é descobrir em que largura a composição deixa de funcionar: texto aperta, ações colidem ou hierarquia desaparece.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Mobile-first começa com a menor composição viável e adiciona espaço quando ele existe. Unidades fluidas, `minmax`, `clamp` e limites de largura reduzem a quantidade de breakpoints e deixam o conteúdo comandar a adaptação.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Defina largura máxima para leitura confortável.","Use `minmax()` e grid responsivo para coleções.","Escolha breakpoint quando o conteúdo quebra, não por marca de aparelho.","Teste zoom, textos longos e orientação."],"title":"Como pensar na prática"},{"body":"Um grid de cards pode usar `grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr))`; ele redistribui espaço sem conhecer modelos de dispositivo.","type":"example","title":"Exemplo aplicado"},{"body":"Esconder conteúdo importante no mobile para “caber” pode resolver layout sacrificando funcionalidade. Primeiro mude a composição.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele um card com título longo, três badges e CTA. Liste quais elementos podem quebrar linha e quais precisam manter largura mínima de toque.","type":"guided_practice","title":"Prática orientada"},{"body":"Responsividade é uma propriedade de produto. Testes devem considerar conteúdo real, zoom e navegação por toque, não apenas screenshots em 375px e 1440px.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Conteúdo define pontos de quebra úteis.","Mobile-first prioriza o essencial.","Layouts fluidos reduzem breakpoints artificiais.","Responsividade inclui toque, zoom e texto longo."]}],"lab_type":"checkpoint","position":3,"objective":"Projetar composição que se adapta ao conteúdo e à largura disponível sem depender de dispositivos específicos.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["O modelo de celular mais vendido.","O ponto em que a composição deixa de funcionar bem.","Sempre 768px por convenção.","A resolução do monitor do desenvolvedor."],"feedback":"Correto. Breakpoint existe para preservar a composição quando o conteúdo precisa mudar de arranjo.","question":"O que deve determinar um breakpoint útil?","feedback_incorrect":"Use o comportamento da interface como critério, não uma lista fixa de aparelhos."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":2,"estimated_minutes":28},{"title":"Formulários: validação, feedback e estados","content":[{"body":"Formulários concentram abandono porque unem linguagem, validação, rede e estados assíncronos. Uma falha pequena — apagar campos após erro ou não indicar qual campo falhou — produz frustração desproporcional.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Validação de cliente oferece feedback rápido; validação de servidor protege o sistema. As duas trabalham juntas. Erros devem ser associados ao campo, preservar entrada válida e permitir correção direta. Durante envio, a UI precisa evitar duplicidade sem parecer travada.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Label visível e associação explícita para campos.","Valide no servidor mesmo quando o navegador já validou.","Preserve valores quando houver erro corrigível.","Modele idle, submitting, success e error."],"title":"Como pensar na prática"},{"body":"Após POST retornar 422 com `fields.email`, a tela mantém nome e telefone, marca o e-mail, exibe a mensagem junto ao campo e move foco para o primeiro erro relevante.","type":"example","title":"Exemplo aplicado"},{"body":"Desabilitar o botão sem qualquer indicador durante uma requisição lenta faz o usuário acreditar que a página travou e tentar recarregar.","type":"mistake","title":"Falha que parece pequena"},{"body":"Defina os estados de um formulário de cadastro e descreva o que acontece se a conexão cair depois do clique em enviar.","type":"guided_practice","title":"Prática orientada"},{"body":"Formulários bons evitam trabalho perdido e chamados de suporte. O backend e o frontend precisam compartilhar as mesmas regras críticas, mesmo que apresentem mensagens diferentes.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Validação do cliente melhora UX; servidor garante regra.","Erro precisa dizer onde e como corrigir.","Estado de envio evita duplicidade.","Falha de rede deve preservar o trabalho."]}],"lab_type":"checkpoint","position":4,"objective":"Construir formulários acessíveis que tratam erro, envio, sucesso e repetição sem perder dados do usuário.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Porque CSS não aceita validação.","Porque o cliente pode ser alterado ou contornado.","Para deixar a página mais pesada.","Porque HTTP não suporta formulários."],"feedback":"Correto. O servidor não pode confiar que a requisição veio da interface oficial.","question":"Por que uma regra crítica precisa ser validada novamente no servidor?","feedback_incorrect":"Validação de UI não é uma barreira de segurança."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":2,"estimated_minutes":30},{"title":"Acessibilidade e performance como requisitos","content":[{"body":"Uma página que demora, salta durante carregamento ou não funciona por teclado tem defeitos de produto mesmo que a lógica esteja correta. Corrigir isso no final costuma exigir refazer componentes e fluxo.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Acessibilidade e performance precisam de orçamento e evidência. Imagens têm dimensões e formatos adequados; componentes não bloqueiam a thread sem necessidade; foco e contraste são testados; carregamento prioriza o que o usuário precisa primeiro.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Teste navegação completa apenas com teclado.","Evite layout shift reservando espaço para mídia.","Carregue recursos não críticos de forma adiada.","Meça antes e depois de otimizar."],"title":"Como pensar na prática"},{"body":"Uma galeria abaixo da dobra usa imagens responsivas, dimensões conhecidas e lazy loading. O hero crítico carrega de forma prioritária e não depende de uma fonte gigante para aparecer.","type":"example","title":"Exemplo aplicado"},{"body":"Otimizar reduzindo tudo até ficar ilegível troca uma métrica por um problema de usabilidade. Performance precisa preservar função.","type":"mistake","title":"Falha que parece pequena"},{"body":"Escolha uma página existente e escreva um checklist de cinco verificações: teclado, foco, texto ampliado, mídia e carregamento lento.","type":"guided_practice","title":"Prática orientada"},{"body":"Qualidade frontend é observável. Lighthouse e outras ferramentas ajudam, mas não substituem teste humano de navegação e fluxos reais.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Acessibilidade é comportamento testável.","Performance deve ter orçamento.","Mídia precisa reservar espaço e tamanho adequado.","Ferramentas automáticas não cobrem toda a experiência."]}],"lab_type":"checkpoint","position":5,"objective":"Usar métricas e testes práticos para evitar que experiência, acessibilidade e velocidade sejam tratadas apenas no fim.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Comparar duas capturas de tela.","Percorrer o fluxo completo usando apenas teclado.","Trocar a cor do fundo.","Abrir o código-fonte sem interagir."],"feedback":"Correto. Navegação por teclado revela foco, ordem e controles inacessíveis.","question":"Qual teste detecta um problema que uma análise puramente visual pode não revelar?","feedback_incorrect":"Acessibilidade inclui interação, não apenas aparência."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":2,"estimated_minutes":32},{"title":"Estado e fluxo de dados em JavaScript","content":[{"body":"Quando cada clique altera diretamente vários elementos da página, o estado real fica escondido na interface. Depois de algumas features, ninguém sabe qual variável ou elemento é a fonte de verdade.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Estado é a representação mínima necessária para descrever o momento atual da aplicação. A interface deve ser derivada dele. Valores calculáveis, como quantidade filtrada, não precisam virar outro estado se podem ser obtidos a partir da fonte.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Escolha uma única fonte de verdade por dado.","Derive valores quando possível.","Atualize estado por eventos explícitos.","Evite estado duplicado em variáveis e DOM."],"title":"Como pensar na prática"},{"body":"Uma lista de tarefas mantém `tasks` e `filter`. A lista visível é derivada com `tasks.filter(...)`; não existe uma segunda variável `visibleTasks` que possa ficar dessincronizada.","type":"example","title":"Exemplo aplicado"},{"body":"Guardar `total`, `items` e `itemCount` separadamente exige lembrar de atualizar três lugares. Se dois podem ser derivados, mantenha apenas a fonte necessária.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele o estado mínimo de um carrinho com itens, cupom e status do checkout. Marque quais valores devem ser derivados.","type":"guided_practice","title":"Prática orientada"},{"body":"Fluxo de dados claro reduz bugs que aparecem apenas após combinações específicas de eventos. Esse princípio continua válido em React e outras bibliotecas.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Estado descreve o momento atual.","Valores derivados não precisam de duplicação.","Eventos devem produzir transições explícitas.","UI confiável reflete uma fonte de verdade."]}],"lab_type":"checkpoint","position":1,"objective":"Modelar estado explícito e derivar interface a partir dele em vez de espalhar mutações pelo DOM.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Manter os dois estados e atualizar manualmente.","Derivar total de items quando necessário.","Salvar total apenas no HTML.","Criar uma variável global para cada item."],"feedback":"Correto. Derivação elimina uma fonte de inconsistência entre estados redundantes.","question":"Se `total` pode ser calculado sempre a partir de `items`, qual estratégia tende a ser mais segura?","feedback_incorrect":"Evite armazenar duas representações quando uma pode ser calculada da outra."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":36},{"title":"Funções, módulos e fronteiras de responsabilidade","content":[{"body":"Uma função que valida, altera DOM, grava localStorage e faz fetch ao mesmo tempo é difícil de testar e reutilizar. Pequenas mudanças exigem montar todo o ambiente.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Fronteiras boas separam cálculo de efeito. Funções puras recebem dados e retornam dados; adaptadores lidam com rede, storage ou interface. Módulos agrupam responsabilidades relacionadas e expõem uma API pequena.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Prefira parâmetros explícitos a dependências globais.","Isole fetch, storage e DOM nas bordas.","Retorne valores ou erros previsíveis.","Exporte o mínimo necessário de cada módulo."],"title":"Como pensar na prática"},{"body":"Uma função `calculateDiscount(order, rules)` pode ser testada sem navegador. Outra função recebe o resultado e atualiza a UI.","type":"example","title":"Exemplo aplicado"},{"body":"Transformar cada linha em uma função não cria arquitetura. A separação precisa acompanhar responsabilidades e pontos de mudança.","type":"mistake","title":"Falha que parece pequena"},{"body":"Pegue o fluxo “salvar preferência”. Separe em validação, persistência e feedback de UI. Escreva a assinatura de cada função.","type":"guided_practice","title":"Prática orientada"},{"body":"Separar lógica de infraestrutura permite trocar framework, API ou banco com menos impacto e torna testes rápidos muito mais simples.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Função pura facilita teste.","Efeitos devem ficar nas bordas.","Módulo expõe contrato pequeno.","Separação acompanha responsabilidade, não tamanho."]}],"lab_type":"checkpoint","position":2,"objective":"Separar lógica pura, efeitos e infraestrutura para tornar código testável e substituível.","xp_reward":130,"difficulty":2,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Uma que lê variáveis globais e altera DOM.","Uma que recebe entradas e retorna um resultado sem efeitos externos.","Uma que faz fetch, alert e localStorage juntos.","Uma que depende do horário atual sem receber relógio."],"feedback":"Correto. Entradas explícitas e ausência de efeitos tornam o comportamento determinístico.","question":"Qual função tende a ser mais fácil de testar?","feedback_incorrect":"Quanto menos ambiente externo a função exige, menor o custo do teste."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":28},{"title":"Assíncrono, fetch e estados de rede","content":[{"body":"Rede não é uma chamada de função local: pode atrasar, falhar, responder fora de ordem ou retornar um erro HTTP com JSON válido. Interface que assume sucesso imediato cria bugs intermitentes.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"`fetch` resolve a Promise mesmo em muitos status de erro HTTP, então o código precisa verificar `response.ok`. A UI deve representar carregamento, vazio, erro e sucesso. Quando buscas se sobrepõem, respostas antigas não devem substituir resultados mais novos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Verifique status HTTP antes de consumir como sucesso.","Use try/catch para falhas de rede e parsing.","Modele loading, empty, error e success.","Considere AbortController para requisições obsoletas."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Uma busca por texto cancela a requisição anterior quando o termo muda. Só a resposta associada ao termo atual pode atualizar os resultados.","kind":"text"},{"body":"const response = await fetch(\"/api/tasks\");\nif (!response.ok) {\n  throw new Error(`HTTP ${response.status}`);\n}\nconst tasks = await response.json();","kind":"code","language":"javascript"}]},{"body":"Usar `await response.json()` e assumir que tudo deu certo transforma um 401 JSON em dado de sucesso e empurra o erro para outra parte da tela.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe o estado de uma busca que pode ficar sem resultados, receber 500, ser cancelada e concluir com itens.","type":"guided_practice","title":"Prática orientada"},{"body":"Concorrência de rede aparece em autocomplete, filtros e dashboards. Tratá-la cedo evita bugs que só surgem em conexões lentas.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["HTTP de erro precisa ser interpretado.","Rede exige estados explícitos.","Respostas podem chegar fora de ordem.","Cancelamento pode proteger a UI de dados obsoletos."]}],"lab_type":"checkpoint","position":3,"objective":"Tratar sucesso, erro, cancelamento e concorrência em operações assíncronas.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Porque JSON só funciona com 200.","Porque respostas HTTP como 404/500 podem resolver a Promise normalmente.","Porque fetch não aceita HTTPS.","Porque o navegador bloqueia qualquer status diferente de 201."],"feedback":"Correto. Falha HTTP e falha de transporte são categorias diferentes.","question":"Por que `fetch()` exige checar `response.ok`?","feedback_incorrect":"Uma Promise resolvida não significa que a operação de negócio teve sucesso."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":30},{"title":"TypeScript como contrato executável","content":[{"body":"Em aplicações grandes, muitos bugs não são algoritmos errados; são formas inesperadas de dados: campo opcional tratado como obrigatório, string usada como número ou status novo não previsto.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"TypeScript adiciona verificação estática, mas seu maior valor aparece quando os tipos modelam o domínio. Uniões discriminadas representam estados; tipos de entrada diferem de entidades persistidas; `unknown` obriga validação antes de confiar em dados externos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Evite `any` quando o dado ainda precisa ser validado.","Modele status como união de valores possíveis.","Separe DTO de entidade quando responsabilidades divergem.","Use narrowing antes de acessar propriedades incertas."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Um estado de requisição pode ser `idle | loading | success(data) | error(message)`. O compilador força o código a tratar cada variante antes de acessar `data`.","kind":"text"},{"body":"type LoadState<T> =\n  | { status: \"idle\" }\n  | { status: \"loading\" }\n  | { status: \"success\"; data: T }\n  | { status: \"error\"; message: string };","kind":"code","language":"typescript"}]},{"body":"Substituir todos os tipos por `any` faz o projeto “compilar”, mas remove justamente a verificação que justificava TypeScript.","type":"mistake","title":"Falha que parece pequena"},{"body":"Modele o resultado de um pagamento com estados pending, approved e rejected. Defina quais campos existem apenas quando aprovado.","type":"guided_practice","title":"Prática orientada"},{"body":"Tipos bem modelados funcionam como documentação verificável e tornam refactors mais seguros, especialmente em contratos usados por várias telas.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Tipo deve representar regras reais do domínio.","Dados externos começam como não confiáveis.","Uniões discriminadas modelam estados com clareza.","`any` deve ser exceção consciente."]}],"lab_type":"checkpoint","position":4,"objective":"Usar tipos para tornar estados inválidos mais difíceis de representar e melhorar integração entre camadas.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["any","unknown","never","void"],"feedback":"Correto. `unknown` impede uso direto até que o valor seja validado ou estreitado.","question":"Qual tipo é mais adequado para um valor externo que ainda não foi validado?","feedback_incorrect":"O objetivo é reconhecer que a origem externa ainda não merece confiança."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":32},{"title":"React: componentes, estado e efeitos","content":[{"body":"React facilita composição, mas não impede arquitetura ruim. Um componente pode acumular busca, formulário, modal, regra de negócio e persistência até se tornar impossível entender a origem de cada atualização.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"Componente deve expressar uma responsabilidade de interface. Props carregam dados/ações para baixo; estado local representa interação local; estado compartilhado sobe até o ancestral comum. Efeitos sincronizam com sistemas externos, não substituem cálculos que poderiam ocorrer durante renderização.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Mantenha estado perto de onde é usado.","Derive valores em render quando possível.","Use efeito para rede, subscrição ou API externa.","Extraia hooks quando reutilizam comportamento, não só linhas."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Um filtro de produtos mantém `query` e recebe `products` por props. `filteredProducts` é calculado no render; não há efeito que copia produtos para outro estado.","kind":"text"},{"body":"function Search({ products }) {\n  const [query, setQuery] = useState(\"\");\n  const visible = products.filter(p =>\n    p.name.toLowerCase().includes(query.toLowerCase())\n  );\n  return <ProductList items={visible} />;\n}","kind":"code","language":"javascript"}]},{"body":"Usar `useEffect` para recalcular toda variável derivada cria render extra e risco de dependências incompletas.","type":"mistake","title":"Falha que parece pequena"},{"body":"Desenhe uma página de tarefas em componentes: filtro, lista, item e formulário. Defina onde `tasks` deve morar e por quê.","type":"guided_practice","title":"Prática orientada"},{"body":"Componentes previsíveis reduzem regressão visual e permitem testar unidades de interação sem montar a aplicação inteira.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Estado deve ter dono claro.","Props comunicam contrato entre componentes.","Efeito sincroniza com o exterior.","Valores derivados não precisam de efeito."]}],"lab_type":"checkpoint","position":5,"objective":"Construir componentes com responsabilidades claras e usar efeitos apenas para sincronização externa.","xp_reward":130,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Somar dois números recebidos por props.","Sincronizar o componente com uma API ou subscrição externa.","Criar uma constante.","Formatar uma string simples."],"feedback":"Correto. Efeitos representam sincronização com algo fora do cálculo puro do render.","question":"Qual é um uso apropriado de `useEffect`?","feedback_incorrect":"Cálculos determinísticos geralmente podem ocorrer diretamente durante renderização."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":34},{"title":"Formulário React com validação de servidor","content":[{"body":"Formulários em React costumam começar simples e crescer até carregar dezenas de booleanos: loading, errorEmail, errorName, success, touched. Sem um modelo explícito, estados contraditórios aparecem.","type":"story","title":"Por que isso aparece em sistemas reais"},{"body":"O formulário deve distinguir valores, erros por campo e estado da submissão. Validação local cobre feedback imediato; a resposta do servidor é autoridade final. Uma tentativa em andamento precisa ter identidade suficiente para impedir duplicidade e ignorar respostas obsoletas.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Mantenha erros por campo em estrutura própria.","Desabilite nova submissão enquanto a operação está em voo quando ela não é idempotente.","Mapeie 422 para campos e preserve valores.","Trate 401/403 diferente de validação."],"title":"Como pensar na prática"},{"type":"example","title":"Exemplo técnico","segments":[{"body":"Após `POST /users`, uma resposta 422 preenche `{email:\"Já cadastrado\"}`; 401 redireciona para autenticação; 500 mostra erro geral sem apagar o formulário.","kind":"text"},{"body":"type FieldErrors = Record<string, string>;\n\nasync function save(values: FormValues) {\n  const r = await fetch(\"/api/users\", {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify(values)\n  });\n  if (r.status === 422) return { ok: false, fields: await r.json() };\n  if (!r.ok) throw new Error(\"Falha ao salvar\");\n  return { ok: true, data: await r.json() };\n}","kind":"code","language":"typescript"}]},{"body":"Transformar qualquer erro em “Confira seus dados” esconde falhas de servidor e dificulta suporte, observabilidade e diagnóstico.","type":"mistake","title":"Falha que parece pequena"},{"body":"Escreva uma tabela com status HTTP 201, 401, 403, 409, 422 e 500 e indique qual reação de UI é adequada em cada um.","type":"guided_practice","title":"Prática orientada"},{"body":"Frontend profissional não mascara a API: ele traduz estados técnicos em próximos passos claros para a pessoa e mantém informação suficiente para observabilidade.","type":"professional_context","title":"Critério profissional"},{"type":"recap","items":["Erro de campo e erro geral são diferentes.","Servidor continua sendo autoridade.","Submissão duplicada precisa de prevenção.","Status HTTP orienta comportamento da interface."]}],"lab_type":"checkpoint","position":6,"objective":"Integrar estado de formulário, validação local, erro estruturado do backend e prevenção de submissão duplicada.","xp_reward":130,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":0,"options":["422 de validação","204 sem corpo","301 redirect","503 como se fosse erro do campo"],"feedback":"Correto. Erros de validação podem ser associados aos campos e corrigidos no mesmo contexto.","question":"Qual resposta normalmente deve preencher erros específicos de campos sem apagar o formulário?","feedback_incorrect":"Procure o status que representa entrada compreensível, porém inválida para a regra."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":3,"estimated_minutes":36}]$lessons$::jsonb)
  as x(module_position int,position int,title text,objective text,estimated_minutes int,content jsonb,lesson_type text,lab_type text,lab_config jsonb,xp_reward int,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.lessons(module_id,title,objective,estimated_minutes,content,position,status,lesson_type,lab_type,lab_config,xp_reward,difficulty)
select m.id,p.title,p.objective,p.estimated_minutes,p.content,p.position,'draft',p.lesson_type,p.lab_type,p.lab_config,p.xp_reward,p.difficulty
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
on conflict(module_id,position) do update set
 title=excluded.title,objective=excluded.objective,estimated_minutes=excluded.estimated_minutes,content=excluded.content,
 lesson_type=excluded.lesson_type,lab_type=excluded.lab_type,lab_config=excluded.lab_config,xp_reward=excluded.xp_reward,
 difficulty=excluded.difficulty,updated_at=now();

with payload as (
  select * from jsonb_to_recordset($assessments$[{"title":"LC Pro Full Stack — M1 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":1,"randomize_questions":true},{"title":"LC Pro Full Stack — M2 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":2,"randomize_questions":true},{"title":"LC Pro Full Stack — M3 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":3,"randomize_questions":true}]$assessments$::jsonb)
  as x(module_position int,title text,pass_score numeric,max_attempts int,randomize_questions boolean)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.assessments(course_id,module_id,title,pass_score,max_attempts,randomize_questions,status)
select c.id,m.id,p.title,p.pass_score,p.max_attempts,p.randomize_questions,'draft'
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
where not exists(
  select 1 from nexora.assessments a where a.course_id=c.id and a.module_id=m.id and a.title=p.title
);

with payload as (
  select * from jsonb_to_recordset($questions$[{"prompt":"Qual requisito está mais próximo de um critério de aceite verificável?","options":[{"id":"c","label":"Ao enviar e-mail inválido, o formulário impede o envio e informa o campo."},{"id":"d","label":"Use React porque é profissional."},{"id":"a","label":"A tela deve ficar moderna."},{"id":"b","label":"O sistema deve ser rápido."}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"c"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. O critério descreve entrada, comportamento e resultado observável.","feedback_incorrect":"Procure uma frase que outra pessoa consiga testar sem interpretar gosto ou intenção."},{"prompt":"Onde a autorização de uma operação sensível deve ser obrigatoriamente validada?","options":[{"id":"a","label":"Somente no botão da interface."},{"id":"b","label":"No backend antes de executar a operação."},{"id":"c","label":"Apenas no CSS da página."},{"id":"d","label":"No navegador do usuário."}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. A autorização precisa ser aplicada numa fronteira controlada pelo servidor.","feedback_incorrect":"A interface melhora UX, mas não é uma barreira de segurança."},{"prompt":"Qual arquivo pode ser versionado com segurança?","options":[{"id":"d","label":"private-key.pem"},{"id":"a","label":".env com a senha real do banco"},{"id":"b","label":".env.example com nomes de variáveis e valores fictícios"},{"id":"c","label":"backup.sql com dados reais de clientes"}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. Um arquivo de exemplo documenta configuração sem expor credenciais.","feedback_incorrect":"Documentação pode ser pública; segredos e dados reais não."},{"prompt":"Qual ação é mais adequada para desfazer um commit já publicado numa branch compartilhada?","options":[{"id":"c","label":"Reescrever todo o histórico com force push."},{"id":"d","label":"Excluir o repositório e clonar novamente."},{"id":"a","label":"Apagar a branch principal."},{"id":"b","label":"Usar revert para criar uma mudança inversa auditável."}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. Revert preserva a história e adiciona uma reversão explícita.","feedback_incorrect":"Em histórico compartilhado, prefira uma mudança auditável a reescrever commits existentes."},{"prompt":"Qual resposta é mais coerente para um JSON válido cujo campo obrigatório está vazio?","options":[{"id":"b","label":"422 com erro estruturado de validação"},{"id":"c","label":"500 porque o usuário errou"},{"id":"d","label":"301 para a página inicial"},{"id":"a","label":"200 com texto 'deu erro'"}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. A requisição chegou ao recurso, mas falhou numa regra de validação.","feedback_incorrect":"Diferencie falha do servidor de entrada que não satisfaz o contrato."},{"prompt":"Qual sequência reduz mais risco antes da implementação?","options":[{"id":"a","label":"Framework → código → requisito → teste"},{"id":"b","label":"Requisito → critério de aceite → arquitetura → implementação → teste"},{"id":"c","label":"CSS → banco → reunião → deploy"},{"id":"d","label":"Deploy → rollback → código → requisito"}],"position":6,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":1,"assessment_title":"LC Pro Full Stack — M1 • Checkpoint","feedback_correct":"Correto. O fluxo começa pelo comportamento esperado e mantém verificabilidade até a entrega.","feedback_incorrect":"Procure uma sequência em que cada etapa produza informação para a seguinte."},{"prompt":"Qual elemento é a melhor base para uma ação que envia um formulário?","options":[{"id":"a","label":"div"},{"id":"b","label":"span"},{"id":"c","label":"button type=\"submit\""},{"id":"d","label":"h3"}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"c"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. O botão nativo já possui semântica e comportamento adequados.","feedback_incorrect":"Escolha o elemento cuja função corresponde à ação."},{"prompt":"Qual abordagem tende a reduzir inconsistência de espaçamento ao longo do produto?","options":[{"id":"c","label":"Adicionar !important a todas as margens."},{"id":"d","label":"Posicionar tudo com absolute."},{"id":"a","label":"Criar um valor novo em cada componente."},{"id":"b","label":"Usar uma escala de tokens recorrentes."}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. Uma escala recorrente transforma espaçamento em regra compartilhada.","feedback_incorrect":"Consistência nasce de poucas decisões reutilizadas, não de ajustes independentes."},{"prompt":"O que deve determinar um breakpoint útil?","options":[{"id":"b","label":"O ponto em que a composição deixa de funcionar bem."},{"id":"c","label":"Sempre 768px por convenção."},{"id":"d","label":"A resolução do monitor do desenvolvedor."},{"id":"a","label":"O modelo de celular mais vendido."}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. Breakpoint existe para preservar a composição quando o conteúdo precisa mudar de arranjo.","feedback_incorrect":"Use o comportamento da interface como critério, não uma lista fixa de aparelhos."},{"prompt":"Por que uma regra crítica precisa ser validada novamente no servidor?","options":[{"id":"a","label":"Porque CSS não aceita validação."},{"id":"b","label":"Porque o cliente pode ser alterado ou contornado."},{"id":"c","label":"Para deixar a página mais pesada."},{"id":"d","label":"Porque HTTP não suporta formulários."}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. O servidor não pode confiar que a requisição veio da interface oficial.","feedback_incorrect":"Validação de UI não é uma barreira de segurança."},{"prompt":"Qual teste detecta um problema que uma análise puramente visual pode não revelar?","options":[{"id":"d","label":"Abrir o código-fonte sem interagir."},{"id":"a","label":"Comparar duas capturas de tela."},{"id":"b","label":"Percorrer o fluxo completo usando apenas teclado."},{"id":"c","label":"Trocar a cor do fundo."}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. Navegação por teclado revela foco, ordem e controles inacessíveis.","feedback_incorrect":"Acessibilidade inclui interação, não apenas aparência."},{"prompt":"Qual decisão melhor preserva responsividade e acessibilidade ao mesmo tempo?","options":[{"id":"c","label":"Ocultar formulários no mobile."},{"id":"d","label":"Desabilitar zoom para estabilizar layout."},{"id":"a","label":"Posicionar todos os elementos com coordenadas fixas."},{"id":"b","label":"Usar elementos semânticos e composição fluida guiada pelo conteúdo."}],"position":6,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":2,"assessment_title":"LC Pro Full Stack — M2 • Checkpoint","feedback_correct":"Correto. Estrutura semântica e layout fluido atendem diferentes modos de uso.","feedback_incorrect":"Evite soluções que dependem de uma viewport ou removem capacidade do usuário."},{"prompt":"Se `total` pode ser calculado sempre a partir de `items`, qual estratégia tende a ser mais segura?","options":[{"id":"b","label":"Derivar total de items quando necessário."},{"id":"c","label":"Salvar total apenas no HTML."},{"id":"d","label":"Criar uma variável global para cada item."},{"id":"a","label":"Manter os dois estados e atualizar manualmente."}],"position":1,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Derivação elimina uma fonte de inconsistência entre estados redundantes.","feedback_incorrect":"Evite armazenar duas representações quando uma pode ser calculada da outra."},{"prompt":"Qual função tende a ser mais fácil de testar?","options":[{"id":"a","label":"Uma que lê variáveis globais e altera DOM."},{"id":"b","label":"Uma que recebe entradas e retorna um resultado sem efeitos externos."},{"id":"c","label":"Uma que faz fetch, alert e localStorage juntos."},{"id":"d","label":"Uma que depende do horário atual sem receber relógio."}],"position":2,"difficulty":2,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Entradas explícitas e ausência de efeitos tornam o comportamento determinístico.","feedback_incorrect":"Quanto menos ambiente externo a função exige, menor o custo do teste."},{"prompt":"Por que `fetch()` exige checar `response.ok`?","options":[{"id":"d","label":"Porque o navegador bloqueia qualquer status diferente de 201."},{"id":"a","label":"Porque JSON só funciona com 200."},{"id":"b","label":"Porque respostas HTTP como 404/500 podem resolver a Promise normalmente."},{"id":"c","label":"Porque fetch não aceita HTTPS."}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Falha HTTP e falha de transporte são categorias diferentes.","feedback_incorrect":"Uma Promise resolvida não significa que a operação de negócio teve sucesso."},{"prompt":"Qual tipo é mais adequado para um valor externo que ainda não foi validado?","options":[{"id":"c","label":"never"},{"id":"d","label":"void"},{"id":"a","label":"any"},{"id":"b","label":"unknown"}],"position":4,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. `unknown` impede uso direto até que o valor seja validado ou estreitado.","feedback_incorrect":"O objetivo é reconhecer que a origem externa ainda não merece confiança."},{"prompt":"Qual é um uso apropriado de `useEffect`?","options":[{"id":"b","label":"Sincronizar o componente com uma API ou subscrição externa."},{"id":"c","label":"Criar uma constante."},{"id":"d","label":"Formatar uma string simples."},{"id":"a","label":"Somar dois números recebidos por props."}],"position":5,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Efeitos representam sincronização com algo fora do cálculo puro do render.","feedback_incorrect":"Cálculos determinísticos geralmente podem ocorrer diretamente durante renderização."},{"prompt":"Qual resposta normalmente deve preencher erros específicos de campos sem apagar o formulário?","options":[{"id":"d","label":"503 como se fosse erro do campo"},{"id":"a","label":"422 de validação"},{"id":"b","label":"204 sem corpo"},{"id":"c","label":"301 redirect"}],"position":6,"difficulty":4,"question_type":"multiple_choice","correct_answer":{"option_id":"a"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Erros de validação podem ser associados aos campos e corrigidos no mesmo contexto.","feedback_incorrect":"Procure o status que representa entrada compreensível, porém inválida para a regra."},{"prompt":"Qual combinação representa uma arquitetura de frontend mais previsível?","options":[{"id":"d","label":"Fetch sem status + erros convertidos em sucesso"},{"id":"a","label":"Estado duplicado + efeitos para tudo + any"},{"id":"b","label":"Fonte de verdade clara + funções isoladas + tipos + estados explícitos de rede"},{"id":"c","label":"Variáveis globais + DOM como banco de dados"}],"position":7,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":3,"assessment_title":"LC Pro Full Stack — M3 • Checkpoint","feedback_correct":"Correto. Essa combinação reduz estados impossíveis e separa responsabilidades.","feedback_incorrect":"Busque a opção que reduz duplicação, explicita contratos e trata incerteza."}]$questions$::jsonb)
  as x(module_position int,assessment_title text,position int,prompt text,question_type text,options jsonb,correct_answer jsonb,feedback_correct text,feedback_incorrect text,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select a.id,p.prompt,p.question_type,p.options,p.correct_answer,p.feedback_correct,p.feedback_incorrect,p.difficulty,p.position
from payload p,c
join nexora.modules m on m.course_id=c.id and m.position=p.module_position
join nexora.assessments a on a.course_id=c.id and a.module_id=m.id and a.title=p.assessment_title
where not exists(select 1 from nexora.questions q where q.assessment_id=a.id and q.position=p.position);
